/**
 * Keeps release status in step with the Git provider. Status normally arrives as it happens:
 * the pipeline calls RlyStatusService when a run ends, and an open release page refreshes itself.
 * Scheduling this class (every 30 minutes is enough) is a safety net for anything missed, and
 * starts any pipeline run a closed page left pending. Scheduled Apex can't make callouts, so the
 * Schedulable hands off to RlySyncWorker.
 *
 * The workflow writes each step's result as JSON to the release-relay-results branch:
 *   results/<request>/scan.json, validate.json, merge.json, deploy.json
 * Results older than the action that asked for them (checks requested, approval) are ignored.
 */
public with sharing class RlySyncJob implements Schedulable {

    public static final String RESULTS_BRANCH = 'release-relay-results';
    private static final Integer BATCH_SIZE = 12; // up to 6 callouts each, under the 100-callout limit
    public static final Set<String> SYNC_STATUSES = new Set<String>{
        'Submitted', 'Workflow running', 'Retrieving', 'Validating', 'PR open', 'Checks failed', 'Ready for approval', 'Rejected', 'Approved', 'Merging', 'Deploying'
    };
    private static final Set<String> CHECK_OK = new Set<String>{ 'Passed', 'Skipped', 'Bypassed', 'Not configured' };

    /**
     * Hands off to RlySyncWorker. A class can't be both Schedulable and Queueable when it's queued
     * (System.AsyncException), so the callouts run in a separate Queueable class.
     */
    public void execute(SchedulableContext ctx) {
        System.enqueueJob(new RlySyncWorker());
    }

    /** Syncs every open release. Called by RlySyncWorker. */
    public static void syncOpenRequests() {
        syncAndSave(new Data().openRequests());
    }

    /** Reads every release's state (callouts), then saves them. */
    public static void syncAndSave(List<RLY_Release__c> reqs) {
        List<RLY_Release__c> changed = sync(reqs);
        Data data = new Data();
        data.save(changed);
    }

    /** Reads GitHub state for each request and returns them updated. Callouts only; the caller saves. */
    public static List<RLY_Release__c> sync(List<RLY_Release__c> reqs) {
        List<RLY_Release__c> changed = new List<RLY_Release__c>();
        Map<String, RlySettings.Connection> connections = new Map<String, RlySettings.Connection>();
        for (RLY_Release__c req : reqs) {
            try {
                String key = req.Connection__c == null ? '' : req.Connection__c;
                if (!connections.containsKey(key)) {
                    connections.put(key, RlySettings.connection(req.Connection__c));
                }
                RlySettings.Connection c = connections.get(key);
                if (String.isNotBlank(req.Pending_Run__c)) {
                    // The page that took the action didn't start the run (closed too soon): start it now.
                    RlyPipeline.startPending(req);
                } else if (c.isGit) {
                    syncOne(req, c, RlyGitProvider.forConnection(c));
                }
            } catch (Exception e) {
                req.Error_Message__c = ('Status sync failed: ' + e.getMessage()).left(2000);
            }
            req.Last_Synced__c = Datetime.now();
            changed.add(req);
        }
        return changed;
    }

    private static void syncOne(RLY_Release__c req, RlySettings.Connection c, RlyGitProvider git) {
        Boolean prChecked = false;
        if (req.Status__c == 'Workflow running') {
            RlyGitProvider.Run run = git.findRun(req.Name, null, req.Run_ID__c);
            if (run != null) {
                req.Run_ID__c = run.id;
                req.Run_URL__c = run.url;
            }
            RlyGitProvider.PullRequest pr = git.findPullRequest(req.Source_Branch__c, req.Target_Branch__c);
            prChecked = true;
            if (pr != null) {
                req.PR_Number__c = pr.num;
                req.PR_URL__c = pr.url;
                req.Error_Message__c = null;
                if (applyPrState(req, pr)) {
                    return;
                }
                req.Status__c = 'PR open';
            } else if (run != null && run.status == 'completed' && run.conclusion != 'success') {
                req.Status__c = 'Failed';
                req.Error_Message__c = 'Workflow run ' + run.conclusion + '. Open the workflow run for the log.';
                return;
            } else {
                return;
            }
        }

        if (!prChecked && (req.Status__c == 'PR open' || req.Status__c == 'Checks failed'
                || req.Status__c == 'Ready for approval' || req.Status__c == 'Rejected')) {
            RlyGitProvider.PullRequest pr = git.findPullRequest(req.Source_Branch__c, req.Target_Branch__c);
            if (pr != null && req.PR_Number__c == null) {
                req.PR_Number__c = pr.num;
                req.PR_URL__c = pr.url;
            }
            if (pr != null && applyPrState(req, pr)) {
                return;
            }
        }

        if (req.Status__c == 'PR open') {
            readChecks(req, git);
            if (req.Scan_Status__c == 'Pending' || req.Validation_Status__c == 'Pending') {
                RlyGitProvider.Run run = git.findRun(req.Name, null, req.Run_ID__c);
                if (run != null && run.status == 'completed' && run.startedAfter(req.Checks_Requested__c)) {
                    // The run ended without writing a result (for example it was cancelled).
                    if (req.Scan_Status__c == 'Pending') { req.Scan_Status__c = 'Error'; }
                    if (req.Validation_Status__c == 'Pending') { req.Validation_Status__c = 'Error'; }
                    req.Error_Message__c = 'The workflow finished without a check result. Open the workflow run, then Re-run checks.';
                }
            }
            decideAfterChecks(req);
            return;
        }

        if (req.Status__c == 'Merging') {
            Map<String, Object> merged = readResult(git, req.Name, 'merge', req.Approved_On__c);
            if (merged == null) {
                RlyGitProvider.Run run = git.findRun(req.Name, 'merge', req.Run_ID__c);
                if (run != null && run.status == 'completed' && run.conclusion != 'success' && run.startedAfter(req.Approved_On__c)) {
                    req.Status__c = 'Failed';
                    req.Error_Message__c = 'The merge didn\'t complete (' + run.conclusion + '). Open the workflow run for the log.';
                    req.Run_URL__c = run.url;
                }
                return;
            }
            if (merged.get('status') != 'Merged') {
                req.Status__c = 'Failed';
                req.Error_Message__c = ('Merge failed: ' + merged.get('message')).left(2000);
                return;
            }
            req.Merge_Commit__c = String.valueOf(merged.get('sha')).left(40);
            if (String.isBlank(req.Target_Environment__c)) {
                req.Status__c = 'Merged';
                req.Deploy_Status__c = 'Not configured';
                return;
            }
            req.Status__c = 'Deploying';
            req.Deploy_Status__c = 'Deploying';
        }

        if (req.Status__c == 'Deploying') {
            Map<String, Object> deployed = readResult(git, req.Name, 'deploy', req.Approved_On__c);
            if (deployed != null) {
                req.Deploy_Result__c = JSON.serialize(deployed).left(131072);
                Boolean ok = deployed.get('status') == 'Deployed';
                req.Deploy_Status__c = ok ? 'Deployed' : 'Failed';
                req.Status__c = ok ? 'Deployed' : 'Deploy failed';
                req.Error_Message__c = ok ? null : ('Deployment failed: ' + deployed.get('message')).left(2000);
                return;
            }
            RlyGitProvider.Run run = git.findRun(req.Name, 'merge', req.Run_ID__c);
            if (run != null && run.status == 'completed' && run.startedAfter(req.Approved_On__c)) {
                req.Deploy_Status__c = 'Failed';
                req.Status__c = 'Deploy failed';
                req.Error_Message__c = 'The workflow finished without a deployment result. Open the workflow run for the log.';
                req.Run_URL__c = run.url;
            }
        }
    }

    /** Pull request merged or closed outside Release Relay. Returns true when that ends the request. */
    private static Boolean applyPrState(RLY_Release__c req, RlyGitProvider.PullRequest pr) {
        if (pr.merged) {
            req.Status__c = 'Merged';
            req.Error_Message__c = 'Merged in GitHub, outside Release Relay approval.';
            return true;
        }
        if (pr.state == 'closed') {
            req.Status__c = 'Closed';
            return true;
        }
        return false;
    }

    /** Copies new scan and validation results onto the request. */
    @TestVisible
    private static void readChecks(RLY_Release__c req, RlyGitProvider git) {
        if (req.Scan_Status__c == null || req.Scan_Status__c == 'Pending') {
            Map<String, Object> scan = readResult(git, req.Name, 'scan', req.Checks_Requested__c);
            if (scan != null) {
                req.Scan_Status__c = checkStatus(scan.get('status'));
                req.Scan_Violations__c = toNumber(scan.get('total'));
                req.Scan_Blocking__c = toNumber(scan.get('blocking'));
                req.Scan_Result__c = JSON.serialize(scan).left(131072);
            }
        }
        if (req.Validation_Status__c == null || req.Validation_Status__c == 'Pending') {
            if (String.isBlank(req.Target_Environment__c)) {
                req.Validation_Status__c = 'Not configured';
            } else {
                Map<String, Object> result = readResult(git, req.Name, 'validate', req.Checks_Requested__c);
                if (result != null) {
                    req.Validation_Status__c = checkStatus(result.get('status'));
                    req.Validation_Result__c = JSON.serialize(result).left(131072);
                }
            }
        }
    }

    /** Ready for approval when both checks are fine, Checks failed when either failed. */
    @TestVisible
    private static void decideAfterChecks(RLY_Release__c req) {
        if (req.Scan_Status__c == 'Pending' || req.Validation_Status__c == 'Pending'
                || req.Scan_Status__c == null || req.Validation_Status__c == null) {
            return;
        }
        if (CHECK_OK.contains(req.Scan_Status__c) && CHECK_OK.contains(req.Validation_Status__c)) {
            req.Status__c = 'Ready for approval';
            req.Approval_Status__c = 'Pending';
        } else {
            req.Status__c = 'Checks failed';
        }
    }

    /** A step's result for this request, or null when missing or older than notBefore. */
    @TestVisible
    private static Map<String, Object> readResult(RlyGitProvider git, String requestName, String step, Datetime notBefore) {
        String raw = git.getFileRaw('results/' + requestName + '/' + step + '.json', RESULTS_BRANCH);
        if (String.isBlank(raw)) {
            return null;
        }
        Map<String, Object> result = (Map<String, Object>) JSON.deserializeUntyped(raw);
        if (notBefore != null) {
            Datetime finished = parseTime(result.get('finishedAt'));
            // Two minutes of leeway for clock differences between GitHub and Salesforce.
            if (finished == null || finished < notBefore.addMinutes(-2)) {
                return null;
            }
        }
        return result;
    }

    private static String checkStatus(Object value) {
        String s = String.valueOf(value);
        return new Set<String>{ 'Passed', 'Failed', 'Skipped', 'Error' }.contains(s) ? s : 'Error';
    }

    private static Decimal toNumber(Object value) {
        try {
            return value == null ? null : Decimal.valueOf(String.valueOf(value));
        } catch (Exception e) {
            return null;
        }
    }

    @TestVisible
    private static Datetime parseTime(Object value) {
        if (value == null) {
            return null;
        }
        try {
            return (Datetime) JSON.deserialize('"' + String.valueOf(value) + '"', Datetime.class);
        } catch (Exception e) {
            return null;
        }
    }

    /** Runs across every request regardless of who raised it. */
    private without sharing class Data {
        public List<RLY_Release__c> openRequests() {
            return [SELECT Id, Name, Status__c, Connection__c, Connection_Type__c, Source_Branch__c, Target_Branch__c, Target_Environment__c,
                           Source_Environment__c, Title__c, Mode__c, Pending_Run__c, Last_Synced__c,
                           Run_ID__c, Run_URL__c, PR_Number__c, PR_URL__c, Error_Message__c, Checks_Requested__c,
                           Scan_Status__c, Scan_Violations__c, Scan_Blocking__c, Scan_Result__c,
                           Validation_Status__c, Validation_Result__c, Approval_Status__c, Approved_On__c,
                           Merge_Commit__c, Deploy_Status__c, Deploy_Result__c
                    FROM RLY_Release__c
                    WHERE Status__c IN :SYNC_STATUSES
                    ORDER BY Last_Synced__c ASC NULLS FIRST
                    LIMIT :BATCH_SIZE];
        }
        public void save(List<RLY_Release__c> reqs) {
            if (!reqs.isEmpty()) {
                update reqs;
            }
        }
    }
}
